CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "username" varchar(50) UNIQUE NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "full_name" varchar(100) NOT NULL,
  "phone" varchar(20) UNIQUE NOT NULL,
  "email" varchar(100) UNIQUE,
  "role" varchar(20) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "failed_attempts" integer NOT NULL DEFAULT 0,
  "locked_until" timestamptz,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "employee_assignments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" bigint NOT NULL,
  "property_id" bigint NOT NULL,
  "assigned_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "is_active" boolean NOT NULL DEFAULT true
);

CREATE TABLE "properties" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "property_code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(150) NOT NULL,
  "address" text NOT NULL,
  "description" text,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "meter_cutoff_day" integer NOT NULL DEFAULT 28,
  "invoice_issue_day" integer NOT NULL DEFAULT 1,
  "late_fee_enabled" boolean NOT NULL DEFAULT false,
  "late_fee_percentage" numeric(5,2) NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "rooms" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "property_id" bigint NOT NULL,
  "floor_number" integer NOT NULL DEFAULT 1,
  "room_code" varchar(30) NOT NULL,
  "base_price" numeric(12,2) NOT NULL,
  "max_occupants" integer NOT NULL DEFAULT 2,
  "area_sqm" numeric(6,2),
  "status" varchar(20) NOT NULL DEFAULT 'AVAILABLE',
  "amenities" text NOT NULL DEFAULT '',
  "internal_note" text NOT NULL DEFAULT '',
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "tenant_profiles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "user_id" bigint UNIQUE,
  "full_name" varchar(100) NOT NULL,
  "identity_number" varchar(20) NOT NULL,
  "phone" varchar(20) NOT NULL,
  "email" varchar(100),
  "date_of_birth" date,
  "hometown" varchar(150),
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "contracts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "contract_code" varchar(50) UNIQUE NOT NULL,
  "room_id" bigint NOT NULL,
  "primary_tenant_id" bigint NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date NOT NULL,
  "actual_checkout_date" date,
  "rental_price" numeric(12,2) NOT NULL,
  "deposit_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "payment_cycle_day" integer NOT NULL DEFAULT 5,
  "initial_electric_index" numeric(10,2) NOT NULL,
  "initial_water_index" numeric(10,2) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'ACTIVE',
  "terms" text NOT NULL DEFAULT '',
  "violation_note" text,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "contract_members" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "contract_id" bigint NOT NULL,
  "full_name" varchar(100) NOT NULL,
  "identity_number" varchar(20),
  "phone" varchar(20),
  "relationship" varchar(50),
  "effective_from" date NOT NULL,
  "effective_to" date,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "service_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "service_code" varchar(30) UNIQUE NOT NULL,
  "name" varchar(100) NOT NULL,
  "service_type" varchar(30) NOT NULL,
  "calculation_type" varchar(30) NOT NULL,
  "unit_name" varchar(30) NOT NULL,
  "is_mandatory" boolean NOT NULL DEFAULT true
);

CREATE TABLE "service_price_configs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "property_id" bigint NOT NULL,
  "service_item_id" bigint NOT NULL,
  "unit_price" numeric(12,2) NOT NULL,
  "effective_from" date NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "meter_readings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "room_id" bigint NOT NULL,
  "contract_id" bigint NOT NULL,
  "billing_period" varchar(7) NOT NULL,
  "meter_type" varchar(20) NOT NULL,
  "old_index" numeric(10,2) NOT NULL,
  "new_index" numeric(10,2) NOT NULL,
  "consumption" numeric(10,2) NOT NULL,
  "reading_date" date NOT NULL,
  "has_anomaly" boolean NOT NULL DEFAULT false,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "consumption_alerts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "meter_reading_id" bigint NOT NULL,
  "meter_type" varchar(20) NOT NULL,
  "baseline_average" numeric(10,2) NOT NULL,
  "current_consumption" numeric(10,2) NOT NULL,
  "percentage_increase" numeric(6,2) NOT NULL,
  "applied_threshold_percentage" numeric(5,2) NOT NULL,
  "alert_severity" varchar(20) NOT NULL DEFAULT 'WARNING',
  "status" varchar(20) NOT NULL DEFAULT 'PENDING',
  "note" text,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "invoices" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "invoice_code" varchar(50) UNIQUE NOT NULL,
  "contract_id" bigint NOT NULL,
  "billing_period" varchar(7) NOT NULL,
  "issue_date" date NOT NULL,
  "due_date" date NOT NULL,
  "total_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "paid_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "balance_due" numeric(12,2) NOT NULL DEFAULT 0,
  "payment_status" varchar(20) NOT NULL DEFAULT 'UNPAID',
  "status" varchar(20) NOT NULL DEFAULT 'DRAFT',
  "has_anomaly_alert" boolean NOT NULL DEFAULT false,
  "is_settlement" boolean NOT NULL DEFAULT false,
  "note" text,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "invoice_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "invoice_id" bigint NOT NULL,
  "service_item_id" bigint,
  "item_name_snapshot" varchar(100) NOT NULL,
  "unit_price_snapshot" numeric(12,2) NOT NULL,
  "quantity" numeric(10,2) NOT NULL,
  "old_index_snapshot" numeric(10,2),
  "new_index_snapshot" numeric(10,2),
  "subtotal" numeric(12,2) NOT NULL,
  "formula_description" varchar(255)
);

CREATE TABLE "payment_transactions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "invoice_id" bigint NOT NULL,
  "transaction_code" varchar(50) UNIQUE NOT NULL,
  "amount" numeric(12,2) NOT NULL,
  "payment_method" varchar(30) NOT NULL DEFAULT 'CASH',
  "payment_date" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "notes" text
);

CREATE TABLE "checkout_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "contract_id" bigint UNIQUE NOT NULL,
  "checkout_date" date NOT NULL,
  "final_electric_index" numeric(10,2) NOT NULL,
  "final_water_index" numeric(10,2) NOT NULL,
  "final_utility_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "damage_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "unpaid_invoices_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "initial_deposit" numeric(12,2) NOT NULL,
  "actual_refund_amount" numeric(12,2) NOT NULL DEFAULT 0,
  "status" varchar(20) NOT NULL DEFAULT 'COMPLETED',
  "notes" text,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE TABLE "maintenance_requests" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "property_id" bigint NOT NULL,
  "room_id" bigint,
  "contract_id" bigint,
  "title" varchar(150) NOT NULL,
  "description" text NOT NULL,
  "category" varchar(50) NOT NULL DEFAULT 'OTHER',
  "priority" varchar(20) NOT NULL,
  "status" varchar(20) NOT NULL DEFAULT 'NEW',
  "image_urls" text NOT NULL DEFAULT '',
  "expected_date" date NOT NULL,
  "actual_cost" numeric(12,2) NOT NULL DEFAULT 0,
  "progress_note" text,
  "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP)
);

CREATE UNIQUE INDEX ON "employee_assignments" ("user_id", "property_id");

CREATE UNIQUE INDEX ON "rooms" ("property_id", "room_code");

CREATE UNIQUE INDEX ON "service_price_configs" ("property_id", "service_item_id", "effective_from");

CREATE UNIQUE INDEX ON "meter_readings" ("contract_id", "billing_period", "meter_type");

CREATE UNIQUE INDEX ON "invoices" ("contract_id", "billing_period");

COMMENT ON COLUMN "users"."role" IS 'ADMIN | STAFF | TENANT';

COMMENT ON COLUMN "users"."status" IS 'ACTIVE | INACTIVE | LOCKED';

COMMENT ON COLUMN "properties"."status" IS 'ACTIVE | INACTIVE';

COMMENT ON COLUMN "rooms"."floor_number" IS 'Gộp từ bảng floors';

COMMENT ON COLUMN "rooms"."status" IS 'AVAILABLE | RENTED | MAINTENANCE';

COMMENT ON COLUMN "contracts"."status" IS 'PENDING | ACTIVE | EXPIRED | TERMINATED';

COMMENT ON COLUMN "contract_members"."effective_from" IS 'Tính ngày-người cho phí PER_PERSON';

COMMENT ON COLUMN "service_items"."service_type" IS 'ELECTRICITY | WATER | FIXED_SERVICE';

COMMENT ON COLUMN "service_items"."calculation_type" IS 'METER_BASED | PER_PERSON | PER_ROOM';

COMMENT ON COLUMN "service_price_configs"."effective_from" IS 'Đơn giá áp dụng tại ngày đầu kỳ';

COMMENT ON COLUMN "meter_readings"."billing_period" IS 'YYYY-MM';

COMMENT ON COLUMN "meter_readings"."meter_type" IS 'ELECTRICITY | WATER';

COMMENT ON COLUMN "consumption_alerts"."meter_type" IS 'ELECTRICITY | WATER';

COMMENT ON COLUMN "consumption_alerts"."alert_severity" IS 'WARNING | CRITICAL';

COMMENT ON COLUMN "consumption_alerts"."status" IS 'PENDING (Chặn phát hành HĐ) | CONFIRMED | DISMISSED';

COMMENT ON COLUMN "invoices"."billing_period" IS 'YYYY-MM';

COMMENT ON COLUMN "invoices"."payment_status" IS 'UNPAID | PARTIALLY_PAID | PAID';

COMMENT ON COLUMN "invoices"."status" IS 'DRAFT | ISSUED | CANCELLED';

COMMENT ON COLUMN "invoices"."is_settlement" IS 'Hóa đơn kỳ cuối khi trả phòng';

COMMENT ON COLUMN "invoice_items"."formula_description" IS 'Lưu công thức tính snapshot';

COMMENT ON COLUMN "payment_transactions"."payment_method" IS 'CASH | BANK_TRANSFER_MANUAL | DEPOSIT_OFFSET | OTHER';

COMMENT ON COLUMN "checkout_records"."actual_refund_amount" IS 'Số âm là số khách còn phải trả thêm';

COMMENT ON COLUMN "checkout_records"."status" IS 'PENDING | COMPLETED';

COMMENT ON COLUMN "maintenance_requests"."priority" IS 'URGENT | NORMAL | LOW';

COMMENT ON COLUMN "maintenance_requests"."status" IS 'NEW | ACCEPTED | IN_PROGRESS | COMPLETED';

ALTER TABLE "employee_assignments" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "employee_assignments" ADD FOREIGN KEY ("property_id") REFERENCES "properties" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "tenant_profiles" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "rooms" ADD FOREIGN KEY ("property_id") REFERENCES "properties" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contracts" ADD FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contracts" ADD FOREIGN KEY ("primary_tenant_id") REFERENCES "tenant_profiles" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "contract_members" ADD FOREIGN KEY ("contract_id") REFERENCES "contracts" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "service_price_configs" ADD FOREIGN KEY ("property_id") REFERENCES "properties" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "service_price_configs" ADD FOREIGN KEY ("service_item_id") REFERENCES "service_items" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meter_readings" ADD FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meter_readings" ADD FOREIGN KEY ("contract_id") REFERENCES "contracts" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consumption_alerts" ADD FOREIGN KEY ("meter_reading_id") REFERENCES "meter_readings" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "invoices" ADD FOREIGN KEY ("contract_id") REFERENCES "contracts" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "invoice_items" ADD FOREIGN KEY ("invoice_id") REFERENCES "invoices" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "invoice_items" ADD FOREIGN KEY ("service_item_id") REFERENCES "service_items" ("id") ON DELETE SET NULL DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "payment_transactions" ADD FOREIGN KEY ("invoice_id") REFERENCES "invoices" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "checkout_records" ADD FOREIGN KEY ("contract_id") REFERENCES "contracts" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "maintenance_requests" ADD FOREIGN KEY ("property_id") REFERENCES "properties" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "maintenance_requests" ADD FOREIGN KEY ("room_id") REFERENCES "rooms" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "maintenance_requests" ADD FOREIGN KEY ("contract_id") REFERENCES "contracts" ("id") DEFERRABLE INITIALLY IMMEDIATE;
